from pathlib import Path

index_path = Path('index.html')
sw_path = Path('service-worker.js')

text = index_path.read_text()

anchor = """    wrap.appendChild(legend);\n    container.appendChild(wrap);\n"""

replacement = """    wrap.appendChild(legend);\n\n    // V1.22.7: first-pass FireBoard analysis using the already-imported samples.\n    const target = Number(state.target);\n    const sortedGroups = [...groups.entries()].sort((a, b) => a[0] - b[0]);\n    const channelStats = sortedGroups.map(([channel, group]) => {\n      const points = [...group.points].sort((a, b) => a.time - b.time);\n      const temps = points.map(point => point.temp);\n      const avg = temps.reduce((sum, value) => sum + value, 0) / Math.max(1, temps.length);\n      const avgAbsTargetError = Number.isFinite(target)\n        ? temps.reduce((sum, value) => sum + Math.abs(value - target), 0) / Math.max(1, temps.length)\n        : Number.POSITIVE_INFINITY;\n      return { channel, group, points, temps, avg, avgAbsTargetError };\n    });\n\n    let likelyPit = null;\n    if (Number.isFinite(target) && channelStats.length) {\n      const namedPit = channelStats.find(stat => /chamber|pit|ambient|grill|smoker/i.test(stat.group.label || ''));\n      likelyPit = namedPit || [...channelStats].sort((a, b) => a.avgAbsTargetError - b.avgAbsTargetError)[0];\n    }\n\n    const formatDuration = ms => {\n      const totalMinutes = Math.max(0, Math.round(ms / 60000));\n      const hours = Math.floor(totalMinutes / 60);\n      const minutes = totalMinutes % 60;\n      return hours ? `${hours}h ${String(minutes).padStart(2, '0')}m` : `${minutes}m`;\n    };\n\n    const weightedRangeDuration = (points, tolerance) => {\n      if (!Number.isFinite(target) || points.length < 2) return { inRange: 0, total: 0 };\n      let inRange = 0, total = 0;\n      for (let i = 0; i < points.length - 1; i++) {\n        const rawDelta = Math.max(0, points[i + 1].time - points[i].time);\n        const delta = Math.min(rawDelta, 5 * 60 * 1000);\n        if (!delta) continue;\n        total += delta;\n        if (Math.abs(points[i].temp - target) <= tolerance) inRange += delta;\n      }\n      return { inRange, total };\n    };\n\n    const firstStablePeriod = (points, tolerance = 10, requiredMs = 10 * 60 * 1000) => {\n      if (!Number.isFinite(target) || points.length < 2) return null;\n      for (let start = 0; start < points.length; start++) {\n        if (Math.abs(points[start].temp - target) > tolerance) continue;\n        const windowEnd = points[start].time + requiredMs;\n        let reached = false;\n        let valid = true;\n        for (let j = start; j < points.length; j++) {\n          if (Math.abs(points[j].temp - target) > tolerance) { valid = false; break; }\n          if (points[j].time >= windowEnd) { reached = true; break; }\n        }\n        if (valid && reached) return points[start].time;\n      }\n      return null;\n    };\n\n    const analysis = document.createElement('div');\n    analysis.className = 'fireboard-analysis';\n    analysis.style.cssText = 'margin-top:12px;padding:10px;background:#171717;border:1px solid #333;border-radius:10px';\n\n    const analysisTitle = document.createElement('strong');\n    analysisTitle.textContent = 'FireBoard Analysis';\n    analysis.appendChild(analysisTitle);\n\n    const summary = document.createElement('div');\n    summary.className = 'sub';\n    summary.style.marginTop = '4px';\n    summary.textContent = Number.isFinite(target)\n      ? `Cook target: ${target.toFixed(0)}°F. Range timing below is based on the likely pit/chamber channel.`\n      : 'No numeric cook target is available, so target-range timing is not shown.';\n    analysis.appendChild(summary);\n\n    channelStats.forEach(stat => {\n      const row = document.createElement('div');\n      row.style.cssText = 'margin-top:9px;padding-top:9px;border-top:1px solid #2b2b2b;font-size:12px';\n      const min = Math.min(...stat.temps);\n      const max = Math.max(...stat.temps);\n      const unit = Number(stat.group.degree) === 1 ? 'C' : Number(stat.group.degree) === 2 ? 'F' : String(stat.group.degree || 'F');\n      const likelyText = likelyPit && stat.channel === likelyPit.channel ? ' — likely pit/chamber' : '';\n      row.textContent = `${stat.group.label}${likelyText}: avg ${stat.avg.toFixed(1)}°${unit}; min ${min.toFixed(1)}°; max ${max.toFixed(1)}°; ${stat.points.length} samples`;
      analysis.appendChild(row);\n    });\n\n    if (likelyPit && Number.isFinite(target)) {\n      const within10 = weightedRangeDuration(likelyPit.points, 10);\n      const within25 = weightedRangeDuration(likelyPit.points, 25);\n      const stableAt = firstStablePeriod(likelyPit.points, 10);\n      const metrics = document.createElement('div');\n      metrics.style.cssText = 'display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:10px';\n      const metricData = [\n        ['Within ±10°F', within10.total ? `${formatDuration(within10.inRange)} (${Math.round(within10.inRange / within10.total * 100)}%)` : '—'],\n        ['Within ±25°F', within25.total ? `${formatDuration(within25.inRange)} (${Math.round(within25.inRange / within25.total * 100)}%)` : '—'],\n        ['10-min stable', stableAt ? formatTime(stableAt) : 'Not reached']\n      ];\n      metricData.forEach(([label, value]) => {\n        const box = document.createElement('div');\n        box.style.cssText = 'background:#202020;border:1px solid #303030;border-radius:9px;padding:8px';\n        const k = document.createElement('div');\n        k.style.cssText = 'font-size:10px;color:#999;text-transform:uppercase';\n        k.textContent = label;\n        const v = document.createElement('div');\n        v.style.cssText = 'font-size:14px;font-weight:700;margin-top:3px';\n        v.textContent = value;\n        box.appendChild(k); box.appendChild(v); metrics.appendChild(box);\n      });\n      analysis.appendChild(metrics);\n    }\n\n    wrap.appendChild(analysis);\n    container.appendChild(wrap);\n"""

if anchor not in text:
    raise SystemExit('V1.22.7 graph insertion anchor not found')
text = text.replace(anchor, replacement, 1)

text = text.replace("headerSub.textContent = 'V1.22.6 Stateful BBQ Control Panel';", "headerSub.textContent = 'V1.22.7 Stateful BBQ Control Panel';", 1)
text = text.replace("V1.22.6 adds an in-app FireBoard temperature graph using imported Supabase telemetry, with all attached channels plotted together.<br><strong>Build 2026-09-13M1</strong>", "V1.22.7 adds first-pass FireBoard analysis beneath the imported temperature graph: per-channel summary statistics, likely pit/chamber identification, target-range time, and first sustained stable period.<br><strong>Build 2026-09-13N</strong>", 1)

index_path.write_text(text)

sw = sw_path.read_text()
old_cache = "const CACHE_NAME = 'ldcooklog-v1-22-6a';"
new_cache = "const CACHE_NAME = 'ldcooklog-v1-22-7';"
if old_cache not in sw:
    raise SystemExit('V1.22.7 service-worker cache anchor not found')
sw_path.write_text(sw.replace(old_cache, new_cache, 1))

print('V1.22.7 FireBoard analysis patch applied.')
